from __future__ import annotations

def validate_positive_images(images: list[tuple[int, int]], target_dim: int) -> bool:
    """Coordinates must be in range and distinct; signs must be ±1."""
    axes: set[int] = set()
    for axis, sign in images:
        if axis < 0 or axis > target_dim or sign not in (-1, 1) or axis in axes:
            return False
        axes.add(axis)
    return True

if __name__ == "__main__":
    examples = [([(0, 1), (2, -1), (3, 1)], 3),
                ([(0, 1), (2, -1), (0, -1)], 3)]
    for images, n in examples:
        print(images, validate_positive_images(images, n))

