from __future__ import annotations

def classify_map(images: list[tuple[int, int]], n: int) -> tuple[bool, tuple[int, int] | None]:
    seen: dict[int, int] = {}
    for j, (axis, sign) in enumerate(images):
        if axis < 0 or axis > n or sign not in (-1, 1):
            raise ValueError("malformed signed target vertex")
        if axis in seen:
            return False, (seen[axis], j)
        seen[axis] = j
    return True, None

from __future__ import annotations

def construct_inclusion(m: int, n: int) -> list[tuple[int, int]]:
    if not (0 <= m <= n):
        raise ValueError("no map exists for these dimensions")
    return [(i, 1) for i in range(m + 1)]

from __future__ import annotations

def suspend(images: list[tuple[int, int]], n: int) -> list[tuple[int, int]]:
    axes = [axis for axis, _ in images]
    if len(axes) != len(set(axes)) or any(axis < 0 or axis > n for axis in axes):
        raise ValueError("input coordinate map is not injective")
    return images + [(n + 1, 1)]

